// Local development orchestration: starts PostgreSQL, Mailpit, Services.Api and Web.App together
// and shows their logs and traces in the Aspire dashboard.

var builder = DistributedApplication.CreateBuilder(args);

// PostgreSQL keeps its data in a named volume. The password is generated by Aspire and stored in
// the user secrets of this project. Reset the data: stop the AppHost, remove the container and the
// volume "gamehub-postgres-data" (see README).
var postgres = builder.AddPostgres("postgres")
    .WithDataVolume("gamehub-postgres-data")
    .WithLifetime(ContainerLifetime.Persistent);

var database = postgres.AddDatabase("gamehub");

// Catches all outgoing mails in development (web UI in the dashboard).
var mailpit = builder.AddMailPit("mailpit");

var api = builder.AddProject<Projects.Services_Api>("api")
    .WithReference(database)
    .WaitFor(database)
    .WithReference(mailpit)
    .WaitFor(mailpit)
    .WithHttpHealthCheck("/health");

builder.AddViteApp("web", "../Web.App")
    .WithReference(api)
    .WaitFor(api);

builder.Build().Run();
